//! hub-core's PyYAML 6.0.3 port against PyYAML itself: golden/yaml_{load,dump,frontmatter,random}.json, generated by
//! backend/parity/gen/gen_yaml_golden.py (inputs: every YAML text/value the backend test suite loads or dumps, the repo's
//! YAML files, a scalar/string matrix, a malformed-document corpus and a seeded random batch). Values use the typed
//! JSON encoding of backend/parity/gen/yaml_codec.py.

mod yaml_support;

use hub_core::yamlsafe;
use serde_json::json;
use yaml_support::{big_stack, dec, enc, golden, report, run_dumps, run_loads, tuples_as_lists};

#[test]
fn golden_loads_match_pyyaml() {
    big_stack(|| {
        let g = golden("yaml_load.json");
        let mut failures = Vec::new();
        let n = run_loads(g.as_array().map_or(&[][..], Vec::as_slice), &mut failures);
        report("loads", n, &failures);
    });
}

#[test]
fn golden_dumps_match_pyyaml() {
    big_stack(|| {
        let g = golden("yaml_dump.json");
        let mut failures = Vec::new();
        let n = run_dumps(g.as_array().map_or(&[][..], Vec::as_slice), &mut failures);
        report("dumps", n, &failures);
    });
}

#[test]
fn golden_frontmatter_matches_pyyaml() {
    big_stack(|| {
        let g = golden("yaml_frontmatter.json");
        let mut failures = Vec::new();
        let mut n = 0;
        for case in g["split"].as_array().map_or(&[][..], Vec::as_slice) {
            let text = case["text"].as_str().unwrap_or_default();
            n += 1;
            let got = match yamlsafe::split_frontmatter_exact(text) {
                Ok((meta, body)) => json!({ "ok": [enc(&hub_core::PyValue::Dict(meta)), body] }),
                Err(yamlsafe::LoadError::Yaml(y)) => json!({ "err": { "message": y.0 } }),
                Err(yamlsafe::LoadError::Python { exc_type, message }) => {
                    json!({ "err": { "py_exc": exc_type, "message": message } })
                }
            };
            let mut want = case.clone();
            if let Some(o) = want.as_object_mut() {
                o.remove("text");
            }
            let want = tuples_as_lists(&want);
            if got != want {
                failures.push(format!("split {text:?}:\n  got  {got}\n  want {want}"));
            }
        }
        for case in g["join"].as_array().map_or(&[][..], Vec::as_slice) {
            n += 1;
            let meta = dec(&case["meta"]);
            let body = case["body"].as_str().unwrap_or_default();
            let got = yamlsafe::join_frontmatter(meta.as_dict().unwrap_or_default(), body);
            if case["out"].as_str() != Some(got.as_str()) {
                failures.push(format!(
                    "join {}:\n  got  {got:?}\n  want {}",
                    case["meta"], case["out"]
                ));
            }
        }
        report("frontmatter", n, &failures);
    });
}

#[test]
fn golden_random_batch_matches_pyyaml() {
    big_stack(|| {
        let g = golden("yaml_random.json");
        let mut failures = Vec::new();
        let mut n = run_dumps(g["dumps"].as_array().map_or(&[][..], Vec::as_slice), &mut failures);
        n += run_loads(g["loads"].as_array().map_or(&[][..], Vec::as_slice), &mut failures);
        report("random batch", n, &failures);
    });
}

/// The adapter golden renders (backend/tests/adapters/golden/*.json, the files the adapters write): every YAML file and
/// every frontmatter head must come back byte for byte from `dump(load(text))` with the option set its writer uses
/// (`dump_yaml`/ADAPTER or merge `_dump_doc`/FRONTMATTER for YAML files; `render_frontmatter`/FRONTMATTER or
/// `join_frontmatter`/CONTENT for frontmatter).
#[test]
fn adapter_golden_yaml_bytes_roundtrip() {
    use hub_core::yaml::{DumpOpts, Loader};
    // the Python backend's adapter goldens (backend/tests/adapters/golden before the cutover), kept as test input
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden/python-adapter-golden");
    let entries = std::fs::read_dir(&dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
    let mut checked = 0;
    let mut failures = Vec::new();
    for entry in entries.flatten() {
        let doc: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(entry.path()).unwrap_or_default()).unwrap_or_default();
        for art in doc["artifacts"].as_array().map_or(&[][..], Vec::as_slice) {
            let (Some(path), Some(content)) = (art["path"].as_str(), art["content"].as_str()) else {
                continue;
            };
            let (text, candidates) = if path.ends_with(".yaml") || path.ends_with(".yml") {
                (content.to_string(), [DumpOpts::ADAPTER, DumpOpts::FRONTMATTER])
            } else if let Some(rest) = content.strip_prefix("---\n")
                && let Some(end) = rest.find("\n---\n")
            {
                (rest[..=end].to_string(), [DumpOpts::FRONTMATTER, DumpOpts::CONTENT])
            } else {
                continue;
            };
            checked += 1;
            let value = hub_core::yaml::load(&text, Loader::Strict).unwrap_or_default();
            if !candidates.iter().any(|o| hub_core::yaml::dump(&value, o) == text) {
                failures.push(format!(
                    "{path}: {text:?} -> {:?}",
                    hub_core::yaml::dump(&value, &candidates[0])
                ));
            }
        }
    }
    assert!(checked > 10, "only {checked} YAML artifacts found");
    report("adapter golden YAML", checked, &failures);
}
